using System;
using System.IO;
using System.IO.Packaging;
using System.Linq;
using System.Windows;
namespace Shiri {
 public static class BackupArchive {public static void Write(string root,string target){using(var package=Package.Open(target,FileMode.Create)){foreach(string file in Directory.GetFiles(root,"*",SearchOption.AllDirectories).Where(x=>!x.EndsWith(".tmp",StringComparison.OrdinalIgnoreCase)&&!x.Substring(root.Length).Split(Path.DirectorySeparatorChar,Path.AltDirectorySeparatorChar).Contains(".journal-webview2")&&!String.Equals(Path.GetFullPath(x),Path.GetFullPath(target),StringComparison.OrdinalIgnoreCase))){string relative="/data/"+file.Substring(root.Length+1).Replace('\\','/');var part=package.CreatePart(PackUriHelper.CreatePartUri(new Uri(relative,UriKind.Relative)),"application/octet-stream",CompressionOption.Normal);using(var input=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))using(var output=part.GetStream())input.CopyTo(output);}}}}
 public partial class Controller {
 async void ExportLocalBackup(){try{foreach(var view in floralViews.ToList())if(!await view.Flush())throw new Exception("日记或便签草稿未能保存，请先处理草稿。");if(path==null)throw new Exception("预览模式没有本机数据目录。");if(!FlushFocus())throw new Exception("专注数据未能保存，请稍后重试。");if(!SaveDiary())throw new Exception("日记尚未成功保存，请先处理草稿。");var d=new Microsoft.Win32.SaveFileDialog{Filter="完整本机备份|*.zip",FileName="拾日-完整备份-"+DateTime.Now.ToString("yyyyMMdd-HHmm")+".zip"};if(d.ShowDialog(Window)!=true)return;BackupArchive.Write(Path.GetDirectoryName(path),d.FileName);C<System.Windows.Controls.TextBlock>("FooterMessage").Text="完整备份已导出，包含日记图片。恢复时关闭程序，将ZIP中的data目录解压到程序旁。";}catch(Exception ex){MessageBox.Show(Window,"备份未完成："+ex.Message);}}
 void RestoreBeforeImport(){try{if(path==null)throw new Exception("预览模式没有备份");string directory=Path.GetDirectoryName(path);string backup=Path.Combine(directory,"before-import-tasks.json"),settings=Path.Combine(directory,"before-import-settings.json");if(!File.Exists(backup)||!File.Exists(settings))throw new Exception("没有导入前备份");var restored=Data.Parse(File.ReadAllText(backup));var restoredPreferences=AppPreferences.Load(settings);if(MessageBox.Show(Window,"恢复上次导入前的数据？当前状态将保留为另一个备份。","恢复",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;string prior=Data.Serialize(state);var priorPreferences=preferences;try{Data.Save(path,restored);AppPreferences.Save(preferencesPath,restoredPreferences);}catch{Data.Save(path,Data.Parse(prior));AppPreferences.Save(preferencesPath,priorPreferences);throw;}File.WriteAllText(backup,prior);AppPreferences.Save(settings,priorPreferences);state=restored;preferences=restoredPreferences;undoJson=null;courseWeek=0;Render();RenderCountdown();}catch(Exception ex){MessageBox.Show(Window,"恢复未完成："+ex.Message);}}
 }
}
